_EXPECTED_LOCALES = {code for code, _ in LANGUAGE_OPTIONS if code != "en"} | {
    "ha"
}
if set(BLOCK_ROWS) != _EXPECTED_LOCALES:
    raise ValueError("Private block catalog locale coverage is incomplete")
if len(BLOCK_KEYS) != 34 or len(set(BLOCK_KEYS)) != len(BLOCK_KEYS):
    raise ValueError("Private block source coverage is invalid")

_formatter = string.Formatter()
BLOCK_CATALOGS: dict[str, dict[str, str]] = {}
for _locale, _row in BLOCK_ROWS.items():
    _values = _row.split("|")
    if _locale == "am":
        while len(_values) < len(BLOCK_KEYS):
            _values.insert(25, "እርስዎ ያገዷቸው አባላት")
        while len(_values) > len(BLOCK_KEYS):
            _values.pop(25)
    if len(_values) != len(BLOCK_KEYS):
        raise ValueError(f"Private block row length is invalid for {_locale}")
    _entries = dict(zip(BLOCK_KEYS, _values, strict=True))
    for _source, _value in _entries.items():
        if not _value.strip() or _value == _source:
            raise ValueError(
                f"Missing private block translation: {_locale}: {_source}"
            )
        _source_slots = Counter(
            name for _, name, _, _ in _formatter.parse(_source) if name
        )
        _value_slots = Counter(
            name for _, name, _, _ in _formatter.parse(_value) if name
        )
        if _source_slots != _value_slots:
            raise ValueError(
                f"Invalid private block placeholders: {_locale}: {_source}"
            )
    BLOCK_CATALOGS[_locale] = _entries
